-- Generated by scripts/app-data-init/app-bookmarks-init/generate-init-sql.mjs
-- Source data: scripts/app-data-init/app-bookmarks-init/initial-bookmarks-and-tags.mjs

BEGIN;

-- Reset APP scope bookmarks/tags.
DELETE FROM "bookmark_tags" bt
USING "bookmarks" b
WHERE bt."bookmark_id" = b."id"
  AND b."scope" = 'APP';

DELETE FROM "bookmark_tags" bt
USING "tags" t
WHERE bt."tag_id" = t."id"
  AND t."scope" = 'APP';

DELETE FROM "bookmarks" WHERE "scope" = 'APP';
DELETE FROM "tags" WHERE "scope" = 'APP';

